mapper.select:
select a.payment_id, a.contract_id, a.write_off_status, CASE a.write_off_status WHEN 'NO_PAID' THEN 10 WHEN 'TO_BE_WRITE_OFF' THEN 40 WHEN 'PART_WRITTEN_OFF' THEN 20 WHEN 'WRITTEN_OFF' THEN 30 ELSE 50 END as sort, a.client_id, a.contract_code, a.cash_flow_item, a.biz_dept_id,a.payment_amount, a.paid_amount, a.apply_payment_date, a.paid_in_date, a.payment_code, a.proj_name from (select a.id as payment_id, a.contract_id, case WHEN a.apply_payment_date > now() THEN 'NO_PAID' ELSE 'TO_BE_WRITE_OFF' END AS write_off_status, a.client_id, a.contract_code, "CREDIT_PAYMENT" as cash_flow_item, b.biz_dept_id,a.apply_payment_amount as payment_amount, (select sum(paid_in_amount) from payment_actual_detail where write_off_status = 'WRITTEN_OFF' and payment_id = a.id) as paid_amount, a.apply_payment_date, a.paid_in_date, a.payment_code, b.proj_name from payment_base_info a,contract_base_info b where a.contract_id = b.id and a.payment_status in ('TAKE_EFFECT', 'FINISHED') and a.write_off_status in ('NO_PAID', 'TO_BE_WRITE_OFF') UNION ALL select a.id as payment_id, a.contract_id, a.write_off_status, a.client_id, a.contract_code, "CREDIT_PAYMENT" as cash_flow_item, b.biz_dept_id,a.apply_payment_amount as payment_amount, (select sum(paid_in_amount) from payment_actual_detail where write_off_status = 'WRITTEN_OFF' and payment_id = a.id) as paid_amount, a.apply_payment_date, a.paid_in_date, a.payment_code, b.proj_name from payment_base_info a,contract_base_info b where a.contract_id = b.id and a.payment_status in ('TAKE_EFFECT', 'FINISHED') and a.write_off_status in ('PART_WRITTEN_OFF', 'WRITTEN_OFF')) a
1=1 and a.apply_payment_date >= #{dto.applyPaymentDateFrom} and #{dto.applyPaymentDateTo} >= a.apply_payment_date and a.client_id=#{dto.clientId}
and a.write_off_status in
#{item}
and a.contract_code like CONCAT('%',#{dto.contractCode},'%')
and a.payment_id is null
and a.biz_dept_id=#{dto.bizDeptId}
UNION ALL select a.payment_id, a.contract_id, a.write_off_status, CASE a.write_off_status WHEN 'NO_PAID' THEN 10 WHEN 'TO_BE_WRITE_OFF' THEN 40 WHEN 'PART_WRITTEN_OFF' THEN 20 WHEN 'WRITTEN_OFF' THEN 30 ELSE 50 END as sort, a.client_id, a.contract_code, a.cash_flow_item, a.biz_dept_id,a.payment_amount, a.paid_amount,a.apply_payment_date,a.paid_in_date, a.payment_code, a.proj_name from ( select a.id as payment_id,a.contract_id, 'WRITTEN_OFF' as write_off_status, a.client_id, a.contract_code, "EARNEST_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_margin_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,(select max(cash_flow_date) from contract_rent_actual where contract_id = b.id) as apply_payment_date,(select max(collection_date) from margin_record_info where margin_id = a.id and record_type in ('REFUND_MARGIN', 'REFUND_MARGIN_DEDUCT', 'REFUND')) as paid_in_date, a.margin_code as payment_code, b.proj_name from margin_base_info a,contract_base_info b where a.contract_id = b.id and (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) = IFNULL(a.plan_margin_amount, 0) UNION ALL select a.id as payment_id,a.contract_id, 'PART_WRITTEN_OFF' as write_off_status, a.client_id, a.contract_code, "EARNEST_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_margin_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,(select max(cash_flow_date) from contract_rent_actual where contract_id = b.id) as apply_payment_date,(select max(collection_date) from margin_record_info where margin_id = a.id and record_type in ('REFUND_MARGIN', 'REFUND_MARGIN_DEDUCT', 'REFUND')) as paid_in_date, a.margin_code as payment_code, b.proj_name from margin_base_info a,contract_base_info b where a.contract_id = b.id and (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) BETWEEN 1 and IFNULL(a.plan_margin_amount -1, 2) UNION ALL select a.id as payment_id,a.contract_id, 'TO_BE_WRITE_OFF' as write_off_status, a.client_id, a.contract_code, "EARNEST_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_margin_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,(select max(cash_flow_date) from contract_rent_actual where contract_id = b.id) as apply_payment_date,(select max(collection_date) from margin_record_info where margin_id = a.id and record_type in ('REFUND_MARGIN', 'REFUND_MARGIN_DEDUCT', 'REFUND')) as paid_in_date, a.margin_code as payment_code, b.proj_name from margin_base_info a,contract_base_info b where a.contract_id = b.id and 0 >= (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) and (select max(cash_flow_date) from contract_rent_actual where contract_id = b.id) > NOW() UNION ALL select a.id as payment_id,a.contract_id, 'NO_PAID' as write_off_status, a.client_id, a.contract_code, "EARNEST_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_margin_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,(select max(cash_flow_date) from contract_rent_actual where contract_id = b.id) as apply_payment_date,(select max(collection_date) from margin_record_info where margin_id = a.id and record_type in ('REFUND_MARGIN', 'REFUND_MARGIN_DEDUCT', 'REFUND')) as paid_in_date, a.margin_code as payment_code, b.proj_name from margin_base_info a,contract_base_info b where a.contract_id = b.id and 0 >=(IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) and NOW() > (select max(cash_flow_date) from contract_rent_actual where contract_id = b.id)) a
1=1
and a.apply_payment_date >= #{dto.applyPaymentDateFrom}
and #{dto.applyPaymentDateTo} >= a.apply_payment_date
and a.client_id=#{dto.clientId} and a.contract_code like CONCAT('%',#{dto.contractCode},'%')
and a.write_off_status in
#{item}
and a.biz_dept_id = #{dto.bizDeptId}
and a.cash_flow_item = #{dto.cashFlowItem}
/*质保金*/ UNION ALL select a.payment_id, a.contract_id, a.write_off_status, CASE a.write_off_status WHEN 'NO_PAID' THEN 10 WHEN 'TO_BE_WRITE_OFF' THEN 40 WHEN 'PART_WRITTEN_OFF' THEN 20 WHEN 'WRITTEN_OFF' THEN 30 ELSE 50 END as sort, a.client_id, a.contract_code, a.cash_flow_item, a.biz_dept_id,a.payment_amount, a.paid_amount,a.apply_payment_date,a.paid_in_date, a.payment_code, a.proj_name from ( select a.id as payment_id,a.contract_id, 'WRITTEN_OFF' as write_off_status, a.client_id, a.contract_code, "RETENTION_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_warranty_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,a.plan_warranty_date as apply_payment_date,(select max(collection_date) from warranty_record_info where warranty_id = a.id and record_type in ('REFUND_MARGIN', 'REFUND_MARGIN_DEDUCT', 'REFUND')) as paid_in_date, a.warranty_code as payment_code, b.proj_name from warranty_base_info a,contract_base_info b where a.contract_id = b.id and (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) = IFNULL(a.plan_warranty_amount, 0) UNION ALL select a.id as payment_id,a.contract_id, 'PART_WRITTEN_OFF' as write_off_status, a.client_id, a.contract_code, "RETENTION_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_warranty_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,a.plan_warranty_date as apply_payment_date,(select max(collection_date) from warranty_record_info where warranty_id = a.id and record_type in ('REFUND_WARRANTY', 'REFUND_WARRANTY_DEDUCT', 'REFUND')) as paid_in_date, a.warranty_code as payment_code, b.proj_name from warranty_base_info a,contract_base_info b where a.contract_id = b.id and (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) BETWEEN 1 and IFNULL(a.plan_warranty_amount -1, 2) UNION ALL select a.id as payment_id,a.contract_id, 'TO_BE_WRITE_OFF' as write_off_status, a.client_id, a.contract_code, "RETENTION_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_warranty_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,a.plan_warranty_date as apply_payment_date,(select max(collection_date) from warranty_record_info where warranty_id = a.id and record_type in ('REFUND_WARRANTY', 'REFUND_WARRANTY_DEDUCT', 'REFUND')) as paid_in_date, a.warranty_code as payment_code, b.proj_name from warranty_base_info a,contract_base_info b where a.contract_id = b.id and 0 >= (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) and a.plan_warranty_date > NOW() UNION ALL select a.id as payment_id,a.contract_id, 'NO_PAID' as write_off_status, a.client_id, a.contract_code, "RETENTION_MONEY" as cash_flow_item, b.biz_dept_id,a.plan_warranty_amount as payment_amount, (IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) as paid_amount,a.plan_warranty_date as apply_payment_date,(select max(collection_date) from warranty_record_info where warranty_id = a.id and record_type in ('REFUND_WARRANTY', 'REFUND_WARRANTY_DEDUCT', 'REFUND')) as paid_in_date, a.warranty_code as payment_code, b.proj_name from warranty_base_info a,contract_base_info b where a.contract_id = b.id and 0 >=(IFNULL(a.back_amount,0)+IFNULL(a.deduct_amount,0)) and NOW() > a.plan_warranty_date) a
1=1
and a.apply_payment_date >= #{dto.applyPaymentDateFrom}
and #{dto.applyPaymentDateTo} >= a.apply_payment_date
and a.client_id=#{dto.clientId} and a.contract_code like CONCAT('%',#{dto.contractCode},'%')
and a.write_off_status in
#{item}
and a.biz_dept_id = #{dto.bizDeptId}
and a.cash_flow_item = #{dto.cashFlowItem}
order by sort asc, apply_payment_date desc
